import{_ as p,a0 as r,w as o,s as d,ao as i,I as a,x as n,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"改進你的 Ansible 劇本的 4 行代碼 | LCTT x X-CMD","titleTemplate":false,"description":"改進你的 Ansible 劇本的 4 行代碼 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"改進你的 Ansible 劇本的 4 行代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"改進你的 Ansible 劇本的 4 行代碼 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20210105 4 lines of code to improve your Ansible play","title":"改進你的 Ansible 劇本的 4 行代碼","tag":"202101","desc":""},"relativePath":"202101/20210105 4 lines of code to improve your Ansible play.md","filePath":"[post].md"}'),u={name:"202101/20210105 4 lines of code to improve your Ansible play.md"};function h(b,s,g,_,f,m){const e=r("Link");return o(),d("div",null,[s[27]||(s[27]=i('<h1 id="改進你的-ansible-劇本的-4-行代碼" tabindex="-1">改進你的 Ansible 劇本的 4 行代碼 <a class="header-anchor" href="#改進你的-ansible-劇本的-4-行代碼" aria-label="Permalink to “改進你的 Ansible 劇本的 4 行代碼”">​</a></h1><blockquote><p>只要付出一點點努力，你就可以幫助下一個人，不只是繪製出安全路徑，還可以留下危險的警告。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/23/225612fowskoyyk1gtwtog.jpg" alt=""></p><p>在Blog圈裏，人們對基礎架構即代碼、持續集成/持續交付（CI/CD）管道、代碼審查和測試製度讚不絕口，但人們很容易忘記，這種精心設計的象牙塔只是一種理想，而不是現實。雖然不完美的系統困擾着我們，但我們必須交付一些東西。</p><p>在系統自動化的過程中，很少有比那些通過粘合 API 創建的象牙塔更脆弱的塔。這是一個脆弱的世界。要讓它“工作起來”，交付它，然後繼續前進，壓力巨大。</p><h3 id="要解決的問題" tabindex="-1">要解決的問題 <a class="header-anchor" href="#要解決的問題" aria-label="Permalink to “要解決的問題”">​</a></h3>',6)),a("p",null,[s[1]||(s[1]=n("想像一個簡單的功能請求：編寫一些 ",-1)),t(e,{href:"https://www.ansible.com/"},{default:l(()=>[...s[0]||(s[0]=[n("Ansible",-1)])]),_:1}),s[2]||(s[2]=n(" 代碼，在外部系統中創建幾條記錄，以記錄一個 VLAN 的一些詳細信息。我最近很想做一些實驗室的管理工作來完成這個任務。這個外部系統是一個常見的",-1)),s[3]||(s[3]=a("ruby",null,[n("互聯網協議地址管理"),a("rt",null,"Internet Protocol Address Management")],-1)),s[4]||(s[4]=n("（IPAM）工具，但對於一個更抽象的",-1)),s[5]||(s[5]=a("ruby",null,[n("配置管理資料庫"),a("rt",null,"Configuration Management DataBase")],-1)),s[6]||(s[6]=n("（CMDB）或一個與網絡無關的記錄來説，困難是一樣的。在這個例子中，我創建一個記錄的直接願望就是讓系統保存記錄而已。",-1))]),s[28]||(s[28]=i(`<p>如果我們的目標是一個超緊湊的、直接的、笨拙的宏，那麼它可能用 100 行代碼就能寫出來。如果我記得 API，我也許能在一個小時內把它敲出來，該代碼的作用不會超過預期，除了確切的成品之外，什麼也沒留下。對它的目的而言是完美的，但是對未來的擴展毫無用處。</p><p>如今，我希望幾乎每個人都能從一個<ruby>角色<rt>role</rt></ruby>和幾個<ruby>任務<rt>task</rt></ruby>文件開始這項任務，準備擴展到十幾個創建、讀取、更新和刪除（CRUD）操作。因為我不瞭解這個 API，我可能會花上幾個小時到幾天的時間，僅僅是擺弄它，弄清楚它的內部模式和工藝，彌和它的功能和我用代碼編寫出來的意圖之間的差距。</p><p>在研究 API 的時候，我發現創建一個 VLAN 記錄需要一個父對象引用 <code>vlan_view_ref</code>。這看起來像一個路徑片段，裏面有隨機字符。也許它是一個哈希，也許它真的是隨機的，我不確定。我猜想，許多在泥濘中掙扎的人，在迫在眉睫的截止日期前，可能會把這個任意的字符串複製粘貼到 Ansible 中，然後繼續混下去。忽略這個<ruby>角色<rt>role</rt></ruby>的實現細節，顯而易見這個<ruby>劇本<rt>playbook</rt></ruby>級的任務應該是這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: &quot;Create VLAN&quot;</span></span>
<span class="line"><span>  include_role:</span></span>
<span class="line"><span>    name: otherthing</span></span>
<span class="line"><span>    tasks_from: vlan_create.yml</span></span>
<span class="line"><span>  vars:</span></span>
<span class="line"><span>    vlan_name: &quot;lab-infra&quot;</span></span>
<span class="line"><span>    vlan_tag: 100</span></span>
<span class="line"><span>    vlan_view_ref: &quot;vlan_view/747f602d-0381&quot;</span></span></code></pre></div><p>不幸的是，除了通過 API，<code>vlan_view_ref</code> 標識符是不可用的，所以即使把它移到<ruby>清單文件<rt>inventory</rt></ruby>或額外的變量中也沒有什麼幫助。<ruby>劇本<rt>playbook</rt></ruby>的用户需要對系統有一些更深入的理解，才能找出正確的引用 ID。</p><p>在實驗室建設的情況下，我會經常重新部署這個記錄系統。因此，這個父對象引用 ID 每天都會發生變化，我不希望每次都要手動找出它。所以，我肯定要按名稱搜索該引用。沒問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Get Lab vlan view reference</span></span>
<span class="line"><span>  include_role:</span></span>
<span class="line"><span>    name: otherthing</span></span>
<span class="line"><span>    tasks_from: search_for.yml</span></span>
<span class="line"><span>  vars:</span></span>
<span class="line"><span>    _resource: vlan_view</span></span>
<span class="line"><span>    _query: &quot;name={{ vlan_parent_view_name }}&quot;</span></span></code></pre></div><p>最終，它進行了一個 REST 調用。這將“返回” 一個 JSON，按照慣例，為了便於在角色外訪問，我把它填充進了 <code>_otherthing_search_result</code> 中，。<code>search_for.yml</code> 的實現是抽象的，它總是返回一個包含零或多個結果的字典。</p><p>正如我讀過的幾乎所有真實世界的 Ansible 代碼所證明的那樣，大多數 Ansible 開發者將會繼續前進，好像一切都很好，並且可以直接訪問預期的單個結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Remember our default vlan view ref</span></span>
<span class="line"><span>  set_fact:</span></span>
<span class="line"><span>    _thatthig_vlan_view_ref: &quot;{{ _otherthing_search_result[0]._ref }}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: &quot;Create VLAN&quot;</span></span>
<span class="line"><span>  include_role:</span></span>
<span class="line"><span>    name: otherthing</span></span>
<span class="line"><span>    tasks_from: vlan_create.yml</span></span>
<span class="line"><span>  vars:</span></span>
<span class="line"><span>    vlan_name: &quot;lab-infra&quot;</span></span>
<span class="line"><span>    vlan_tag: 100</span></span>
<span class="line"><span>    vlan_view_ref: &quot;{{ vlan_parent_view_name }}&quot;</span></span></code></pre></div><p>但有時 <code>_otherthing_search_result[0]</code> 是未定義的，所以 <code>_thatthig_vlan_view_ref</code> 也將是未定義的。很有可能是因為代碼運行在不同的真實環境中，而有人忘記了在清單中或在命令列中更新 <code>{{ vlan_parent_view_name }}</code>。或者，無論公平與否，也許有人進入了工具的圖形用户界面（GUI），刪除了記錄或更改了它的名稱什麼的。</p><p>我知道你在想什麼。</p><p><em>“好吧，不要這樣做。這是一個沒有啞巴的場所。不要那麼笨。”</em>。</p><p>也許我對這種情況還算滿意，反駁道：“Ansible 會很正確的告訴你<code>錯誤是：list 對象沒有元素 0</code>，甚至會帶個行號。你還想怎樣？”作為開發者，我當然知道這句話的意思 —— 我剛寫的代碼。我剛從三天的和 API 鬥智鬥勇中走出來，我的腦子很清醒。</p><h3 id="明天是另一個故事" tabindex="-1">明天是另一個故事 <a class="header-anchor" href="#明天是另一個故事" aria-label="Permalink to “明天是另一個故事”">​</a></h3><p>但是到了明天，我可能會忘記什麼是父對象引用，我肯定會忘記第 30 行上的內容。如果一個月後出了問題，就算你能找到我，我也得花一個下午的時間重新解讀 API 指南，才能搞清楚到底出了什麼問題。</p>`,16)),a("p",null,[s[8]||(s[8]=n("而如果我出門了呢？如果我把代碼交給了一個運維團隊，也許是一個實習生通過 ",-1)),t(e,{href:"https://www.ansible.com/products/tower"},{default:l(()=>[...s[7]||(s[7]=[n("Tower",-1)])]),_:1}),s[9]||(s[9]=n(" 來運行，把 ",-1)),s[10]||(s[10]=a("code",null,"vlan_view_name",-1)),s[11]||(s[11]=n(" 手動輸入到表單之類的東西呢？那第 30 行出的問題是對他們沒有幫助的。",-1))]),s[29]||(s[29]=i(`<p>你説，加註釋吧! 嗯，是的。我可以在代碼中寫一些梗概，以幫助下週或下個月的開發人員。這對運行代碼的人沒有幫助，他的“工作”剛剛失敗，當然對於企業也無濟於事。</p><p>記住，我們此刻無所不能。在寫代碼或者跳過寫代碼的時候，我們是站在實力和知識的立場上進行的。我們花了幾個小時，甚至幾天的時間，研究了文檔、現實、其他 bug、其他問題，我們留下了代碼、註釋，甚至可能還有文檔。我們寫的代碼是分享成功的，而成功正是我們用户想要的。但是在這種學習中也有很多失敗的地方，我們也可以留下這些。</p><h3 id="在代碼中留言" tabindex="-1">在代碼中留言 <a class="header-anchor" href="#在代碼中留言" aria-label="Permalink to “在代碼中留言”">​</a></h3><p>“第 30 行有錯誤”對任何人都沒有幫助。至少，我可以用更好的錯誤信息來處理明顯的錯誤情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  - name: Fail if zero vlan views returned</span></span>
<span class="line"><span>     fail:</span></span>
<span class="line"><span>       msg: &quot;Got 0 results from searching for VLAN view {{ vlan_parent_view_name }}. Please verify exists in otherthing, and is accessible by the service account.&quot;</span></span>
<span class="line"><span>     when: _otherthing_search_result | length == 0</span></span></code></pre></div><p>在這四行代碼中（沒有額外的思考），我把具體的、有用的建議留給了下一個人 —— 那個無助的運維團隊成員，或者更有可能是一個月後的我 —— 這是關於現實世界中的問題，其實根本不是關於代碼的。這條消息可以讓任何人發現一個簡單的複製/粘貼錯誤，或者記錄系統發生了變化。不需要 Ansible 知識，不需要凌晨 3 點給開發人員發短信“看看第 30 行”。</p><p>但是等等！還有更多！</p><p>在瞭解 <code>otherthing</code> 的過程中，我瞭解到它在一個關鍵的方面，嗯，還挺笨的。它的許多記錄類型（如果不是全部的話）沒有唯一性約束，可能存在幾個相同的記錄。VLAN 視圖被定義為有一個名稱、一個開始 ID 和一個結束 ID；其他記錄類型也同樣簡單，顯然這應該是一個唯一的元組 —— 基於現實和資料庫規範化的抽象概念。但 <code>otherthing</code> 允許重複的元組，儘管在概念上講永遠不可能。</p><p>在我的實驗室裏，我很樂意嘗試並記住不要這樣做。在企業生產環境中，我可能會寫一個策略。不管是哪種方式，經驗告訴我，系統會被破壞，會在倒霉的時候被破壞，而且可能需要很長時間才能讓這些問題發酵成，嗯，一個問題。</p><p>對於 “第 30 行有錯誤”，一個本來有豐富經驗的 Ansible 開發者可能會認識到這是“記錄沒有找到”，而不用知道其他的事情就足以解決這個問題。但如果 <code>_otherthing_search_result[0]</code> 只有有時是正確的 <code>vlan_view_ref</code>，那就糟糕多了，它讓整個世界被破壞，而悄無聲息。而這個錯誤可能完全表現在其他地方，也許六個月後的安全審計會將其標記為記錄保存不一致，如果有多種工具和人工訪問方式，可能需要幾天或幾周的時間才能發現這個特定代碼出錯的事實。</p><p>在幾天對 API 的摸索中，我學到了這一點。我不是在找問題，如果有記錄，我沒有看到。所以我來到了這篇文章的重點。我沒有因為它是一個實驗室，修復它，然後繼續前進而忽略了這種不可能的情況，而是花了兩分鐘留下了_代碼_ —— 不是註釋，不是心理筆記，不是文檔 —— 而是會一直運行的代碼，涵蓋了這種不可能的情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  - name: Fail if &gt; 1 views returned</span></span>
<span class="line"><span>     fail:</span></span>
<span class="line"><span>       msg: &quot;Got {{ _otherthing_search_result | length }} results from searching for VLAN view {{ vlan_parent_view_name }}. Otherthing allows this, but is not handled by this code.&quot;</span></span>
<span class="line"><span>     when: _otherthing_search_result | length &gt; 1</span></span></code></pre></div><p>我手動創建了失敗條件，所以我可以手動測試這個條件。我希望它永遠不會在實際使用中運行，但我覺得它會。</p><p>如果（當）這個錯誤發生在生產環境中，那麼有人可以決定該怎麼做。我希望他們能修復壞數據。如果它經常發生，我希望他們能追蹤到另一個損壞的系統。如果他們要求刪除這段代碼，而這段代碼做了未定義和錯誤的事情，那是他們的特權，也是我不想工作的地方。代碼是不完美的，但它是完整的。這是匠人的工作。</p><p>現實世界中的自動化是一個迭代的過程，它與不完美的系統進行鬥爭，並平等地使用。它永遠不會處理所有的特殊情況。它甚至可能無法處理所有的正常情況。通過 Lint、代碼審查和驗收測試的工作代碼是處理安全和所需路徑的代碼。只要付出一點點努力，你就可以幫助下一個人，不僅僅是繪製安全路徑，還可以對你發現的危險留下警告。</p><hr>`,16)),a("p",null,[s[13]||(s[13]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/21/1/improve-ansible-play"},{default:l(()=>[...s[12]||(s[12]=[n("https://opensource.com/article/21/1/improve-ansible-play",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/jeffwarncia"},{default:l(()=>[...s[14]||(s[14]=[n("Jeff Warncia",-1)])]),_:1}),s[19]||(s[19]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[15]||(s[15]=[n("lujun9972",-1)])]),_:1}),s[20]||(s[20]=n(" 譯者：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1}),s[21]||(s[21]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...s[23]||(s[23]=[n("Linux中國",-1)])]),_:1}),s[26]||(s[26]=n(" 榮譽推出",-1))])])}const y=p(u,[["render",h]]);export{k as __pageData,y as default};
